30: // Cumulative normal distribution function
31: static inline float CND(float X) {
32:     float L = fabsf(X);
33: 
34:     float k = 1.f / (1.f + 0.2316419f * L);
35:     float k2 = k * k;
36:     float k3 = k2 * k;
37:     float k4 = k2 * k2;
38:     float k5 = k3 * k2;
39: 
40:     const float invSqrt2Pi = 0.39894228040f;
41:     float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
42:     w *= invSqrt2Pi * expf(-L * L * .5f);
43: 
44:     if (X > 0.f)
45:         w = 1.f - w;
46:     return w;
47: }
