94: extern "C" void run(const void* input1, const void* input2, void* output, int n, int parameter, int threads) {
95:     float* a = (float*)input1;
96:     float* result = (float*)output;
97: 
98:     // Use the direct serial implementation when one worker or one output per
99:     // requested worker is sufficient.
100:     if (threads <= 1 || n <= threads) {
101:         black_scholes_serial(a, a + n, a + 2 * n, a + 3 * n, a + 4 * n, result, n);
102:         return;
103:     }
104: 
105:     // Partition contiguous output ranges using the actual team size, so any
106:     // team size supplied by the runtime covers every index exactly once.
107: #pragma omp parallel num_threads(threads)
108:     {
109:         const int team_size = omp_get_num_threads();
110:         const int tid = omp_get_thread_num();
111:         const int quotient = n / team_size;
112:         const int remainder = n % team_size;
113:         const int begin = tid * quotient + (tid < remainder ? tid : remainder);
114:         const int end = begin + quotient + (tid < remainder ? 1 : 0);
115: 
116:         for (int i = begin; i < end; ++i) {
117:             float S = a[i], X = a[n + i];
118:             float T = a[2 * n + i], r = a[3 * n + i];
119:             float v = a[4 * n + i];
120: 
121:             float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
122:             float d2 = d1 - v * sqrtf(T);
123: 
124:             result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
125:         }
126:     }
