49: void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
50:     for (int i = 0; i < count; ++i) {
51:         float S = Sa[i], X = Xa[i];
52:         float T = Ta[i], r = ra[i];
53:         float v = va[i];
54: 
55:         float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
56:         float d2 = d1 - v * sqrtf(T);
57: 
58:         result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
