65:     for (int i = 0; i < count; ++i) {
66:         float S = Sa[i], X = Xa[i];
67:         float T = Ta[i], r = ra[i];
68:         float v = va[i];
69: 
70:         float dt = T / BINOMIAL_NUM;
71:         float u = expf(v * sqrtf(dt));
72:         float d = 1.f / u;
73:         float disc = expf(r * dt);
74:         float Pu = (disc - d) / (u - d);
75: 
76:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
77:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
78:             V[j] = std::max(0.f, X - S * upow);
79:         }
80: 
81:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
82:             for (int k = 0; k < j; ++k)
83:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
84: 
85:         result[i] = V[0];
86:     }
87: }
